"""Golden-set evaluation: schema, scoring, aggregation.

Knows nothing about ONNX — it takes a Runtime and asks it questions. The
dataset is HELD-OUT measurement and never enters the index; contrast
chat/knowledge/*.md, which is corpus and does.
"""

import json
from dataclasses import dataclass
from pathlib import Path

from portfolio_rag.config import settings

CASE_TYPES = ("positive", "off_topic", "injection")
CELL_COMPOSITION = {"positive": 12, "off_topic": 4, "injection": 4}
GOLDEN_PATH = settings.chat_root / "eval" / "golden.jsonl"
# Generated by scripts/run_eval.py --update-baseline, read by tests/test_golden.py.
# Defined here so the CLI and the test share one definition.
BASELINE_PATH = settings.resolve_path("data/eval_baseline.json")


@dataclass(frozen=True)
class GoldenCase:
    id: str
    role: str
    lang: str
    type: str
    q: str
    expected_urls: tuple[str, ...] = ()
    # 1-4 proper nouns / technical terms that must appear in the retrieved text.
    # Page-level expected_urls says "right page"; these say "right passage".
    expected_keywords: tuple[str, ...] = ()
    note: str = ""

    @property
    def cell(self) -> str:
        return f"{self.role}/{self.lang}"


def load_cases(path: Path = GOLDEN_PATH) -> list[GoldenCase]:
    cases: list[GoldenCase] = []
    for lineno, line in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
        line = line.strip()
        if not line or line.startswith("//"):
            continue
        try:
            raw = json.loads(line)
        except json.JSONDecodeError as err:
            raise ValueError(f"{path.name}:{lineno}: invalid JSON — {err}") from err
        missing = {"id", "role", "lang", "type", "q"} - set(raw)
        if missing:
            raise ValueError(f"{path.name}:{lineno}: missing field(s) {sorted(missing)}")
        cases.append(
            GoldenCase(
                id=raw["id"],
                role=raw["role"],
                lang=raw["lang"],
                type=raw["type"],
                q=raw["q"],
                expected_urls=tuple(raw.get("expected_urls", ())),
                expected_keywords=tuple(raw.get("expected_keywords", ())),
                note=raw.get("note", ""),
            )
        )
    return cases
